-- Scoped direct grading. Only results and idempotency fingerprints are persisted.
begin;
create table public.school_paper_templates (
 id uuid primary key default gen_random_uuid(), name text not null check(length(trim(name)) between 2 and 120),
 subject text check(subject in ('Tin học','Tiếng Anh')), groups jsonb not null check(jsonb_typeof(groups)='array'),
 version int not null default 1, deleted_at timestamptz, created_by text references public.school_accounts(username), updated_at timestamptz not null default now()
);
alter table public.school_paper_templates enable row level security;
revoke all on public.school_paper_templates from anon,authenticated;
grant select on public.school_paper_templates to authenticated;
grant all on public.school_paper_templates to service_role;
create policy school_template_read on public.school_paper_templates for select to authenticated using(public.school_is_member() and (subject is null or public.school_can_grade(subject)));
alter table public.school_exams add column template_id uuid references public.school_paper_templates(id), add column template_name text not null default '', add column paper_template jsonb, add column deleted_at timestamptz;
alter table public.school_exams alter column semester set default 1;
alter table public.school_exams alter column kind set default 'regular';
create table public.school_capture_receipts (
 id uuid primary key default gen_random_uuid(), exam_id uuid not null references public.school_exams(id), session_id uuid not null references public.school_capture_sessions(id),
 request_id uuid not null, image_hash text not null check(image_hash ~ '^[0-9a-f]{64}$'), student_id text not null,
 grade_id uuid not null references public.school_grades(id), grade_version int not null, variant text not null,
 score numeric not null, max_score numeric not null, created_at timestamptz not null default now(), unique(session_id,request_id), unique(exam_id,image_hash)
);
alter table public.school_capture_receipts enable row level security;
revoke all on public.school_capture_receipts from public,anon,authenticated;
grant all on public.school_capture_receipts to service_role;
create or replace function public.school_save_exam(p_actor text,p_exam jsonb,p_version int,p_roster jsonb) returns public.school_exams language plpgsql security definer set search_path='' as $$
declare old public.school_exams%rowtype; saved public.school_exams%rowtype; item jsonb;
begin
 select * into old from public.school_exams where id=(p_exam->>'id')::uuid for update;
 if not public.school_grade_actor(p_actor,p_exam->>'subject') or (old.id is not null and not public.school_grade_actor(p_actor,old.subject)) then raise exception 'Forbidden' using errcode='42501'; end if;
 if (old.id is null and p_version<>0) or (old.id is not null and old.version<>p_version) then raise exception 'Revision conflict' using errcode='PT409'; end if;
 if old.deleted_at is not null or old.archived then raise exception 'Bài thi đã ngừng sử dụng.' using errcode='22023'; end if;
 if old.id is not null and (old.class_id<>p_exam->>'class_id' or old.subject<>p_exam->>'subject') then raise exception 'Giữ nguyên lớp và môn theo danh sách dự thi.' using errcode='22023'; end if;
 if old.id is not null and exists(select 1 from public.school_grades g where g.exam_id=old.id) and (old.scoring is distinct from p_exam->'scoring' or old.answer_keys is distinct from p_exam->'answer_keys' or old.paper_template is distinct from p_exam->'paper_template') then raise exception 'Đã có lịch sử điểm; tạo bài thi mới để đổi mẫu phiếu, đáp án hoặc thang điểm.' using errcode='22023'; end if;
 insert into public.school_exams(id,school_year,semester,class_id,class_name,subject,title,kind,weight,exam_date,scoring,answer_keys,created_by,template_id,template_name,paper_template)
 values((p_exam->>'id')::uuid,p_exam->>'school_year',coalesce((p_exam->>'semester')::int,1),p_exam->>'class_id',p_exam->>'class_name',p_exam->>'subject',p_exam->>'title','regular',(p_exam->>'weight')::numeric,(p_exam->>'exam_date')::date,p_exam->'scoring',p_exam->'answer_keys',p_actor,(p_exam->>'template_id')::uuid,coalesce(p_exam->>'template_name',''),p_exam->'paper_template')
 on conflict(id) do update set school_year=excluded.school_year,class_name=excluded.class_name,title=excluded.title,weight=excluded.weight,exam_date=excluded.exam_date,scoring=excluded.scoring,answer_keys=excluded.answer_keys,template_id=excluded.template_id,template_name=excluded.template_name,paper_template=excluded.paper_template,version=school_exams.version+1,updated_at=now() returning * into saved;
 if old.id is null then for item in select value from jsonb_array_elements(p_roster) loop insert into public.school_exam_candidates values(saved.id,item->>'student_id',item->>'student_name',item->>'candidate_number'); end loop; end if;
 return saved;
end $$;
create function public.school_delete_empty_exam(p_actor text,p_exam uuid,p_version int) returns void language plpgsql security definer set search_path='' as $$
declare e public.school_exams%rowtype;
begin
 select * into e from public.school_exams where id=p_exam for update;
 if e.id is null or not public.school_grade_actor(p_actor,e.subject) then raise exception 'Forbidden' using errcode='42501'; end if;
 if e.version<>p_version then raise exception 'Revision conflict' using errcode='PT409'; end if;
 if exists(select 1 from public.school_grades where exam_id=p_exam) then raise exception 'Bài thi đã có lịch sử điểm. Dùng lưu trữ để giữ kết quả học sinh.' using errcode='22023'; end if;
 update public.school_exams set deleted_at=now(),version=version+1,updated_at=now() where id=p_exam;
 update public.school_capture_sessions set active=false where exam_id=p_exam;
end $$;
create function public.school_capture_grade(p_session uuid,p_hash text,p_request uuid,p_image_hash text,p_student text,p_exam_version int,p_grade jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare e public.school_exams%rowtype; s public.school_capture_sessions%rowtype; c public.school_exam_candidates%rowtype; old public.school_grades%rowtype; saved public.school_grades%rowtype; receipt public.school_capture_receipts%rowtype;
begin
 select e1.* into e from public.school_exams e1 join public.school_capture_sessions s1 on s1.exam_id=e1.id where s1.id=p_session for update of e1;
 select * into s from public.school_capture_sessions where id=p_session for update;
 if s.id is null or not s.active or s.expires_at<=now() or s.token_hash<>p_hash or e.id is null or e.archived or e.deleted_at is not null or not public.school_grade_actor(s.created_by,e.subject) then raise exception 'Phiên chấm đã đóng hoặc hết quyền. Quét mã QR mới.' using errcode='PT410'; end if;
 select * into receipt from public.school_capture_receipts where (session_id=p_session and request_id=p_request) or (exam_id=e.id and image_hash=p_image_hash) order by created_at limit 1;
 if receipt.id is not null then
  select * into saved from public.school_grades where id=receipt.grade_id;
  if receipt.student_id<>p_student or receipt.image_hash<>p_image_hash or receipt.variant<>p_grade->>'variant' then raise exception 'Ảnh hoặc lượt gửi đã được dùng cho học sinh khác. Kiểm tra lại bài đang chụp.' using errcode='PT409'; end if;
  if saved.deleted_at is not null or saved.version<>receipt.grade_version then raise exception 'Điểm đã được giáo viên chỉnh sửa. Làm mới danh sách.' using errcode='PT409'; end if;
  return jsonb_build_object('duplicate',true,'grade',to_jsonb(saved));
 end if;
 if e.version<>p_exam_version then raise exception 'Đáp án hoặc mẫu phiếu vừa thay đổi. Tải lại rồi chụp lại.' using errcode='PT409'; end if;
 if s.upload_count>=s.max_uploads then raise exception 'Phiên đã đủ số bài. Mở phiên mới.' using errcode='22023'; end if;
 select * into c from public.school_exam_candidates where exam_id=e.id and student_id=p_student;
 if c.student_id is null then raise exception 'Học sinh không thuộc danh sách của bài thi này.' using errcode='22023'; end if;
 select * into old from public.school_grades where exam_id=e.id and student_id=p_student for update;
 if old.id is not null and old.deleted_at is null then raise exception 'Học sinh đã có điểm. Sửa điểm trên máy tính nếu cần, tránh ghi đè khi chụp trùng.' using errcode='PT409'; end if;
 insert into public.school_grades(exam_id,student_id,student_name,candidate_number,score,max_score,note,source,variant,reviewed_by)
 values(e.id,p_student,c.student_name,c.candidate_number,(p_grade->>'score')::numeric,(p_grade->>'max_score')::numeric,'Chấm tự động từ điện thoại; ảnh không được lưu.','scan',p_grade->>'variant',s.created_by)
 on conflict(exam_id,student_id) do update set student_name=excluded.student_name,candidate_number=excluded.candidate_number,score=excluded.score,max_score=excluded.max_score,note=excluded.note,source='scan',scan_id=null,variant=excluded.variant,answers=null,reviewed_by=s.created_by,updated_at=now(),version=school_grades.version+1,deleted_at=null returning * into saved;
 insert into public.school_grade_history(exam_id,grade_id,actor,action,previous_value,next_value) values(e.id,saved.id,s.created_by,case when old.id is null then 'created' else 'updated' end,to_jsonb(old),to_jsonb(saved));
 insert into public.school_capture_receipts(exam_id,session_id,request_id,image_hash,student_id,grade_id,grade_version,variant,score,max_score) values(e.id,p_session,p_request,p_image_hash,p_student,saved.id,saved.version,saved.variant,saved.score,saved.max_score);
 update public.school_capture_sessions set upload_count=upload_count+1 where id=p_session;
 return jsonb_build_object('duplicate',false,'grade',to_jsonb(saved));
end $$;
revoke all on function public.school_capture_grade(uuid,text,uuid,text,text,int,jsonb), public.school_delete_empty_exam(text,uuid,int) from public,anon,authenticated;
grant execute on function public.school_capture_grade(uuid,text,uuid,text,text,int,jsonb), public.school_delete_empty_exam(text,uuid,int) to service_role;
